<?php
$modules = is_array($args['modules'] ?? null) ? $args['modules'] : [];
if ($modules === []) return;
?><section class="contextual-content-discovery" aria-label="Nội dung liên quan đã có"><?php foreach ($modules as $module): $kind = (string) ($module['kind'] ?? 'entity'); $items = is_array($module['items'] ?? null) ? $module['items'] : []; if ($items === []) continue; ?><section class="contextual-discovery-module discovery-kind-<?php echo esc_attr($kind); ?>"><div class="section-head"><div><p class="eyebrow">Đang có trong hồ sơ</p><h2><?php echo esc_html((string) ($module['title'] ?? 'Liên quan')); ?></h2></div></div><div class="compact-discovery-list"><?php foreach ($items as $item): $title = nhk_v3_public_brand_text(trim((string) ($item['title'] ?? $item['name'] ?? ''))); $url = nhk_v3_public_url($item['url'] ?? null); if ($kind === 'media') { $visual = nhk_v3_media_presentation($item); $url = nhk_v3_media_content_url($item); } if ($title === '' || $url === '') continue; ?><article class="compact-discovery-item"><?php if ($kind === 'media' && $visual['url'] !== ''): ?><a class="compact-discovery-thumb" href="<?php echo esc_url($url); ?>"><img src="<?php echo esc_url($visual['url']); ?>" alt="<?php echo esc_attr($title); ?>" loading="lazy" decoding="async"></a><?php elseif ($kind === 'video'): ?><?php get_template_part('template-parts/presentation/video-card', null, ['item' => $item, 'compact' => true]); ?><?php endif; ?><a class="compact-discovery-link" href="<?php echo esc_url($url); ?>"><strong><?php echo esc_html($title); ?></strong></a></article><?php endforeach; ?></div></section><?php endforeach; ?></section>
